Lemma usage_walk : forall (usp ap : Z) (gp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    F fc (m : word -> option byte) (lo argc : Z) (ptrs : list word) (p0 : word),
  argc <> 2 -> 0 <= argc <= 1024 ->
  stk asegs m lo usp -> SEGTOP_A <= lo -> lo + 0x100000 <= usp -> usp mod 16 = 0 -> usp < 2^47 ->
  u64arr asegs m ap ptrs -> nth_error ptrs 0 = Some p0 -> usp < ap -> ap + 8 <= 2^47 ->
  stderr_cells m -> mem_inv asegs m ->
  evt asegs (fun ms' => exists m', ms' = entry_st (Z_to_bv 64 0x96070) (Z_to_bv 64 (usp - 80)) gp (Z_to_bv 64 TP_A) t0 t1 t2
                                    (Z_to_bv 64 2) s1 (Z_to_bv 64 STDERR_FILE) (Z_to_bv 64 FMT_usage) p0 a3 a4 a5 a6 a7
